import React, { useState, useEffect } from 'react';
import '../styles/Team.css';
import PopUp from '../components/PopUp';

const Team = () => {
  const [allPokemon, setAllPokemon] = useState([]);
  const [search, setSearch] = useState('');
  const [filtered, setFiltered] = useState([]);
  const [team, setTeam] = useState([]);
  const [selectedPokemon, setSelectedPokemon] = useState(null);

  useEffect(() => {
    const fetchPokemon = async () => {
      const res = await fetch('https://pokeapi.co/api/v2/pokemon?limit=1000');
      const data = await res.json();
      setAllPokemon(data.results);
    };
    fetchPokemon();
  }, []);

  useEffect(() => {
    if (!search) {
      setFiltered([]);
      return;
    }
    const results = allPokemon.filter(p =>
      p.name.toLowerCase().includes(search.toLowerCase())
    );
    setFiltered(results.slice(0, 10));
  }, [search, allPokemon]);

  const addToTeam = async (pokemon) => {
    if (team.length >= 6 || team.find(p => p.name === pokemon.name)) return;
    const res = await fetch(pokemon.url);
    const data = await res.json();
    setTeam([...team, data]);
    setSearch('');
    setFiltered([]);
  };

  const removeFromTeam = (name) => {
    setTeam(team.filter(p => p.name !== name));
  };

  const clearTeam = () => setTeam([]);

  const handleCardClick = (pokemon) => {
    setSelectedPokemon(pokemon);
  };

  return (
    <div className="team-container">
      <h1 className="team-title">Tu equipo Pokémon</h1>

      <div className="search-box">
        <input
          type="text"
          placeholder="Buscar Pokémon..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
        {filtered.length > 0 && (
          <ul className="search-results">
            {filtered.map(p => (
              <li key={p.name} onClick={() => addToTeam(p)}>
                {p.name.charAt(0).toUpperCase() + p.name.slice(1)}
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className="team-grid single-line">
        {[...Array(6)].map((_, i) => (
          <div className="team-slot" key={i}>
            {team[i] ? (
              <div className="team-member" onClick={() => handleCardClick(team[i])}>
                <img src={team[i].sprites.front_default} alt={team[i].name} />
                <p>{team[i].name.charAt(0).toUpperCase() + team[i].name.slice(1)}</p>
                <div className="team-types">
                  {team[i].types.map((t) => (
                    <span
                      key={t.type.name}
                      className={`type-badge type-${t.type.name}`}
                    >
                      {t.type.name}
                    </span>
                  ))}
                </div>
                <button onClick={(e) => { e.stopPropagation(); removeFromTeam(team[i].name); }}>✕</button>
              </div>
            ) : (
              <span className="empty-slot">Slot vacío</span>
            )}
          </div>
        ))}
      </div>

      {team.length > 0 && (
        <button className="clear-btn" onClick={clearTeam}>Limpiar equipo</button>
      )}

      {selectedPokemon && (
        <PopUp pokemon={selectedPokemon} onClose={() => setSelectedPokemon(null)} />
      )}
    </div>
  );
};

export default Team;
